"use strict";

/* Solopreneur GitHub Command Center — frontend logic.
 * Consumes static JSON generated by scripts/fetch_github_data.py.
 * No build step, no dependencies, no browser-side GitHub API calls.
 */

const CONFIG = {
  storageKey: "sgcc-v1",
  staleHours: 12,
  defaultVisible: [
    "name", "core_purpose", "last_push", "days_since_push",
    "recent_functionality", "latest_commit", "activity_status", "open_issues",
  ],
};

const FIELDS = [
  { key: "name", label: "Repository", sortable: true, cell: "repo" },
  { key: "core_purpose", label: "Core Purpose", cell: "wrap" },
  { key: "last_push", label: "Last Push", sortable: true, cell: "time" },
  { key: "days_since_push", label: "Days Ago", sortable: true, cell: "number" },
  { key: "recent_functionality", label: "Recent Functionality", cell: "wrap" },
  { key: "latest_commit", label: "Latest Commit", cell: "wrap" },
  { key: "activity_status", label: "Activity", cell: "status" },
  { key: "open_issues", label: "Open Issues", sortable: true, cell: "number" },
  { key: "url", label: "Repository URL", cell: "link" },
  { key: "description", label: "Description", cell: "wrap" },
  { key: "latest_commit_date", label: "Latest Commit Date", cell: "time" },
  { key: "recent_commit_summary", label: "Recent Commit Summary", cell: "wrap" },
  { key: "primary_language", label: "Primary Language" },
  { key: "languages", label: "Languages", cell: "list" },
  { key: "topics", label: "Topics", cell: "list" },
  { key: "default_branch", label: "Default Branch" },
  { key: "visibility", label: "Visibility" },
  { key: "stars", label: "Stars", sortable: true, cell: "number" },
  { key: "forks", label: "Forks", cell: "number" },
  { key: "size", label: "Size (KB)", cell: "number" },
  { key: "created_at", label: "Created", cell: "time" },
  { key: "updated_at", label: "Updated", cell: "time" },
  { key: "is_fork", label: "Fork", cell: "bool" },
  { key: "is_archived", label: "Archived", cell: "bool" },
  { key: "has_readme", label: "Has README", cell: "bool" },
  { key: "homepage", label: "Homepage", cell: "link" },
];

const SEARCH_KEYS = [
  "name", "description", "core_purpose", "topics", "languages",
  "recent_functionality", "recent_commit_summary", "latest_commit",
];

const defaults = {
  count: "10",
  days: "all",
  search: "",
  includeArchived: false,
  includeForks: true,
  sortKey: "last_push",
  sortDir: -1,
  visible: [...CONFIG.defaultVisible],
};

let state = loadState();
let repos = [];
let feed = [];
let meta = null;

/* ------------------------------------------------------------ state */

function loadState() {
  try {
    const raw = JSON.parse(localStorage.getItem(CONFIG.storageKey));
    if (!raw || typeof raw !== "object") return { ...defaults };
    return {
      ...defaults, ...raw,
      visible: Array.isArray(raw.visible) && raw.visible.length ? raw.visible : defaults.visible,
    };
  } catch {
    return { ...defaults };
  }
}

function saveState() {
  localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
}

/* ---------------------------------------------------------- helpers */

function esc(s) {
  return String(s ?? "").replace(/[&<>"']/g, c => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  }[c]));
}

function relTime(iso) {
  if (!iso) return "—";
  const mins = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (Number.isNaN(mins)) return "—";
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  if (days < 30) return `${days}d ago`;
  return `${Math.floor(days / 30)}mo ago`;
}

function absTime(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  return d.toLocaleString(undefined, {
    day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit",
  });
}

function rawValue(field, repo) {
  const v = repo[field.key];
  if (field.cell === "list") return Array.isArray(v) ? v.join(", ") : "";
  if (field.cell === "bool") return v ? "Yes" : "No";
  if (field.cell === "time") return v ? absTime(v) : "";
  return v ?? "";
}

/* --------------------------------------------------------- filtering */

function filteredRows() {
  const q = state.search.trim().toLowerCase();
  let rows = repos.filter(r => {
    if (!state.includeArchived && r.is_archived) return false;
    if (!state.includeForks && r.is_fork) return false;
    if (state.days !== "all") {
      const d = Number(state.days);
      if (r.days_since_push === null || r.days_since_push > d) return false;
    }
    if (q) {
      const hay = SEARCH_KEYS
        .map(k => (Array.isArray(r[k]) ? r[k].join(" ") : r[k]) || "")
        .join(" ")
        .toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  const k = state.sortKey;
  const dir = state.sortDir;
  rows.sort((a, b) => {
    const va = a[k] ?? "";
    const vb = b[k] ?? "";
    const cmp = (typeof va === "number" && typeof vb === "number")
      ? va - vb
      : String(va).localeCompare(String(vb));
    return cmp * dir;
  });

  if (state.count !== "all") rows = rows.slice(0, Number(state.count));
  return rows;
}

/* ------------------------------------------------------------ render */

function visibleFields() {
  return FIELDS.filter(f => state.visible.includes(f.key));
}

function renderHead() {
  const head = document.getElementById("repo-head");
  head.innerHTML = visibleFields().map(f => {
    if (!f.sortable) return `<th scope="col">${esc(f.label)}</th>`;
    const arrow = state.sortKey === f.key ? `<span class="arrow">${state.sortDir === 1 ? "▲" : "▼"}</span>` : "";
    return `<th scope="col" class="sortable" data-key="${f.key}" tabindex="0" role="button"
      aria-label="Sort by ${esc(f.label)}">${esc(f.label)}${arrow}</th>`;
  }).join("");
  head.querySelectorAll("th.sortable").forEach(th => {
    th.addEventListener("click", () => toggleSort(th.dataset.key));
    th.addEventListener("keydown", e => {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggleSort(th.dataset.key); }
    });
  });
}

function toggleSort(key) {
  if (state.sortKey === key) {
    state.sortDir *= -1;
  } else {
    state.sortKey = key;
    state.sortDir = key === "name" ? 1 : -1;
  }
  saveState();
  renderAll();
}

function cellHtml(field, repo) {
  const v = repo[field.key];
  switch (field.cell) {
    case "repo": {
      const fork = repo.is_fork ? `<span class="fork-flag">fork</span>` : "";
      const arch = repo.is_archived ? `<span class="fork-flag">archived</span>` : "";
      return `<td class="nowrap"><a class="repo-name" href="${esc(repo.url)}">${esc(v)}</a>${fork}${arch}</td>`;
    }
    case "time":
      return `<td class="nowrap" title="${esc(absTime(v))}">${esc(relTime(v))}</td>`;
    case "status":
      return `<td class="nowrap"><span class="badge badge-${esc(v || "UNKNOWN")}">${esc(v || "UNKNOWN")}</span></td>`;
    case "link":
      return v ? `<td class="nowrap"><a href="${esc(v)}">${esc(v.replace(/^https?:\/\//, ""))}</a></td>` : `<td class="muted">—</td>`;
    case "list":
      return `<td>${esc((v || []).join(", ")) || '<span class="muted">—</span>'}</td>`;
    case "bool":
      return `<td class="nowrap">${v ? "Yes" : '<span class="muted">No</span>'}</td>`;
    case "number":
      return `<td class="nowrap">${v ?? '<span class="muted">—</span>'}</td>`;
    case "wrap":
      return `<td class="wrap">${esc(v) || '<span class="muted">—</span>'}</td>`;
    default:
      return `<td>${esc(v) || '<span class="muted">—</span>'}</td>`;
  }
}

function renderBody(rows) {
  const body = document.getElementById("repo-body");
  if (!rows.length) {
    body.innerHTML = `<tr><td colspan="${visibleFields().length}" class="muted" style="text-align:center;padding:24px">
      No repositories match the current filters.</td></tr>`;
    return;
  }
  body.innerHTML = rows.map(r =>
    `<tr>${visibleFields().map(f => cellHtml(f, r)).join("")}</tr>`
  ).join("");
}

function renderFieldsPanel() {
  const list = document.getElementById("fields-list");
  list.innerHTML = FIELDS.map(f => `
    <label><input type="checkbox" data-key="${f.key}"
      ${state.visible.includes(f.key) ? "checked" : ""}> ${esc(f.label)}</label>
  `).join("");
  list.querySelectorAll("input").forEach(cb => {
    cb.addEventListener("change", () => {
      const key = cb.dataset.key;
      state.visible = cb.checked
        ? [...state.visible, key]
        : state.visible.filter(k => k !== key);
      saveState();
      renderAll();
    });
  });
}

function feedLabel(isoDate) {
  const day = isoDate.slice(0, 10);
  const today = new Date().toISOString().slice(0, 10);
  const yest = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
  if (day === today) return "Today";
  if (day === yest) return "Yesterday";
  return new Date(day + "T00:00:00Z").toLocaleDateString(undefined, { day: "numeric", month: "short" });
}

function renderFeed() {
  const el = document.getElementById("activity-feed");
  const items = feed.slice(0, 15);
  if (!items.length) {
    el.innerHTML = '<p class="muted">No recent commit activity in the tracked window.</p>';
    return;
  }
  let html = "";
  let lastLabel = null;
  for (const it of items) {
    const label = feedLabel(it.date);
    if (label !== lastLabel) {
      html += `<div class="feed-day">${esc(label)}</div>`;
      lastLabel = label;
    }
    const time = new Date(it.date).toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
    html += `<div class="feed-item">
      <span class="feed-time">${esc(time)}</span>
      <a class="feed-repo" href="https://github.com/${esc(meta.user)}/${esc(it.repo)}">${esc(it.repo)}</a>
      <a class="feed-msg" href="${esc(it.url)}">${esc(it.message)}</a>
    </div>`;
  }
  el.innerHTML = html;
}

function renderHeader() {
  const freshness = document.getElementById("freshness");
  const banner = document.getElementById("status-banner");
  if (!meta) {
    freshness.textContent = "Dashboard data unavailable.";
    banner.hidden = false;
    banner.textContent = "Could not load dashboard data. The GitHub Action may not have run yet.";
    return;
  }
  freshness.textContent = `Last updated: ${absTime(meta.generated_at)}`;
  document.getElementById("repo-stats").textContent =
    `${meta.repo_count} repositories tracked · ${meta.archived_count} archived · ` +
    `${meta.detail_repos} with recent detail`;
  const ageHours = (Date.now() - new Date(meta.generated_at).getTime()) / 3600000;
  if (ageHours > CONFIG.staleHours || meta.status !== "ok") {
    banner.hidden = false;
    banner.textContent = `Latest data update ${meta.status === "ok" ? "is stale" : "failed"} — ` +
      `showing data from ${absTime(meta.generated_at)}. ` +
      (meta.errors?.length ? `Errors: ${meta.errors.map(e => e.repo).join(", ")}` : "");
  } else {
    banner.hidden = true;
  }
}

function renderAll() {
  renderHead();
  const rows = filteredRows();
  renderBody(rows);
  renderFeed();
  renderHeader();
  const total = repos.filter(r =>
    (state.includeArchived || !r.is_archived) && (state.includeForks || !r.is_fork) &&
    (state.days === "all" || (r.days_since_push !== null && r.days_since_push <= Number(state.days))) &&
    (!state.search.trim() || SEARCH_KEYS.map(k => (Array.isArray(r[k]) ? r[k].join(" ") : r[k]) || "")
      .join(" ").toLowerCase().includes(state.search.trim().toLowerCase()))
  ).length;
  document.getElementById("match-count").textContent =
    `Showing ${rows.length} of ${total} matching · ${repos.length} total`;
}

/* ------------------------------------------------------------ CSV */

function exportCSV(rows) {
  const fields = visibleFields();
  const escCsv = v => `"${String(v ?? "").replace(/"/g, '""')}"`;
  const lines = [fields.map(f => escCsv(f.label)).join(",")];
  for (const r of rows) lines.push(fields.map(f => escCsv(rawValue(f, r))).join(","));
  const blob = new Blob([lines.join("\r\n")], { type: "text/csv;charset=utf-8" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `github-solopreneur-dashboard-${new Date().toISOString().slice(0, 10)}.csv`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(a.href);
}

/* ----------------------------------------------------------- wiring */

function wireControls() {
  const count = document.getElementById("f-count");
  const days = document.getElementById("f-days");
  const search = document.getElementById("f-search");
  const archived = document.getElementById("f-archived");
  const forks = document.getElementById("f-forks");

  count.value = state.count;
  days.value = state.days;
  search.value = state.search;
  archived.checked = state.includeArchived;
  forks.checked = state.includeForks;

  count.addEventListener("change", () => { state.count = count.value; saveState(); renderAll(); });
  days.addEventListener("change", () => { state.days = days.value; saveState(); renderAll(); });
  archived.addEventListener("change", () => { state.includeArchived = archived.checked; saveState(); renderAll(); });
  forks.addEventListener("change", () => { state.includeForks = forks.checked; saveState(); renderAll(); });

  let debounce = null;
  search.addEventListener("input", () => {
    clearTimeout(debounce);
    debounce = setTimeout(() => { state.search = search.value; saveState(); renderAll(); }, 150);
  });

  document.getElementById("csv-btn").addEventListener("click", () => exportCSV(filteredRows()));
}

/* ------------------------------------------------------------ init */

async function init() {
  wireControls();
  renderFieldsPanel();
  try {
    const [reposRes, activityRes, metaRes] = await Promise.all([
      fetch("data/repos.json"),
      fetch("data/activity.json"),
      fetch("data/metadata.json"),
    ]);
    if (!reposRes.ok) throw new Error(`repos.json HTTP ${reposRes.status}`);
    const reposData = await reposRes.json();
    feed = activityRes.ok ? (await activityRes.json()).feed || [] : [];
    meta = metaRes.ok ? await metaRes.json() : null;
    repos = reposData.repos || [];
  } catch (err) {
    console.error(err);
    meta = null;
  }
  renderAll();
}

document.addEventListener("DOMContentLoaded", init);
